INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('education', 'jee/chemistry', 'atomic-structure', 'The Aufbau Principle states that electrons fill atomic orbitals in order of:', '["Increasing orbital energy", "Decreasing orbital energy", "Increasing principal quantum number only", "Random order"]', 0, 'The Aufbau Principle states that electrons occupy the lowest-energy available orbitals first, filling orbitals in order of increasing energy.', 'beginner'),
('education', 'jee/chemistry', 'atomic-structure', 'The Pauli Exclusion Principle states that no two electrons in the same atom can have:', '["The same set of all four quantum numbers", "The same principal quantum number", "The same spin quantum number only", "The same orbital shape"]', 0, 'The Pauli Exclusion Principle requires every electron in an atom to have a unique combination of all four quantum numbers (n, l, ml, ms).', 'beginner'),
('education', 'jee/chemistry', 'atomic-structure', 'Hund''s Rule of Maximum Multiplicity states that electrons fill degenerate orbitals:', '["Singly first, with parallel spins, before any pairing occurs", "In pairs immediately, from the lowest orbital", "Randomly, regardless of orbital energy", "Only after all lower-energy shells are completely full"]', 0, 'Hund''s Rule states that electrons occupy degenerate (equal-energy) orbitals singly, with parallel spins, before any orbital gets a second electron.', 'beginner'),
('education', 'jee/chemistry', 'atomic-structure', 'The maximum number of electrons that can occupy a shell with principal quantum number n is:', '["2n^2", "n^2", "2n", "n"]', 0, 'The maximum electron capacity of a shell is 2n^2, derived from summing the capacities of its subshells.', 'intermediate'),
('education', 'jee/chemistry', 'atomic-structure', 'The correct electronic configuration of neon (atomic number 10) is:', '["1s^2 2s^2 2p^6", "1s^2 2s^2 2p^5", "1s^2 2s^2", "1s^2 2s^2 2p^6 3s^2"]', 0, 'Neon has 10 electrons, filling 1s (2) + 2s (2) + 2p (6) = 10, giving 1s^2 2s^2 2p^6, a complete octet.', 'intermediate'),
('education', 'jee/chemistry', 'chemical-bonding', 'VSEPR theory predicts the geometry of a molecule based on:', '["Minimizing repulsion between electron pairs around the central atom", "The molecular mass of the compound", "The number of hydrogen bonds present", "The boiling point of the compound"]', 0, 'Valence Shell Electron Pair Repulsion (VSEPR) theory predicts molecular shape by arranging electron pairs around the central atom to minimize their mutual repulsion.', 'beginner'),
('education', 'jee/chemistry', 'chemical-bonding', 'An sp3 hybridized central atom typically has a molecular geometry of:', '["Tetrahedral (bond angle ~109.5 degrees)", "Linear (180 degrees)", "Trigonal planar (120 degrees)", "Square planar (90 degrees)"]', 0, 'sp3 hybridization involves four equivalent hybrid orbitals arranged tetrahedrally, giving a bond angle of approximately 109.5 degrees.', 'intermediate'),
('education', 'jee/chemistry', 'chemical-bonding', 'Hydrogen bonding occurs when a hydrogen atom bonded to a highly electronegative atom (such as N, O, or F) interacts with:', '["A lone pair on another highly electronegative atom", "Any carbon atom", "A noble gas atom", "A metal cation only"]', 0, 'Hydrogen bonding is a strong dipole-dipole interaction between an H atom bonded to N/O/F and a lone pair on a nearby N, O, or F atom.', 'beginner'),
('education', 'jee/chemistry', 'chemical-bonding', 'A covalent bond is formed primarily by:', '["Sharing of electron pairs between two atoms", "Complete transfer of electrons from one atom to another", "Overlap of atomic nuclei", "Attraction between oppositely charged ions"]', 0, 'A covalent bond forms when two atoms share one or more pairs of electrons, in contrast to an ionic bond where electrons are fully transferred.', 'beginner'),
('education', 'jee/chemistry', 'chemical-bonding', 'In Molecular Orbital Theory, the bond order of a diatomic molecule is calculated as:', '["(Number of bonding electrons - number of antibonding electrons) / 2", "Number of bonding electrons alone", "Number of antibonding electrons alone", "(Bonding electrons + antibonding electrons) / 2"]', 0, 'Bond order = (bonding electrons - antibonding electrons) / 2, a measure of the net bonding strength predicted by Molecular Orbital Theory.', 'intermediate'),
('education', 'jee/chemistry', 'equilibrium', 'Le Chatelier''s Principle states that when a system at equilibrium is subjected to a change, the system will:', '["Shift in the direction that counteracts (partially offsets) the imposed change", "Immediately reach a new, unrelated equilibrium state", "Remain completely unaffected", "Shift to increase the imposed change"]', 0, 'Le Chatelier''s Principle: a system at equilibrium responds to a disturbance by shifting in the direction that tends to reduce (counteract) that disturbance.', 'beginner'),
('education', 'jee/chemistry', 'equilibrium', 'The ionic product of water (Kw) at 25 degrees Celsius has a value of:', '["10^-14", "10^-7", "10^-1", "1"]', 0, 'At 25 degrees Celsius, Kw = [H+][OH-] = 10^-14, the standard reference value used throughout the pH/pOH scale.', 'beginner'),
('education', 'jee/chemistry', 'equilibrium', 'At 25 degrees Celsius, the sum of pH and pOH of any aqueous solution equals:', '["14", "7", "1", "0"]', 0, 'Since Kw = 10^-14 at 25 degrees Celsius, pH + pOH = -log(Kw) = 14 for any aqueous solution at that temperature.', 'beginner'),
('education', 'jee/chemistry', 'equilibrium', 'According to the Ostwald dilution law, the degree of dissociation of a weak acid:', '["Increases upon dilution", "Decreases upon dilution", "Remains unaffected by dilution", "Becomes zero upon dilution"]', 0, 'Diluting a weak electrolyte solution increases its degree of dissociation, since the equilibrium shifts to produce more ions as concentration decreases.', 'intermediate'),
('education', 'jee/chemistry', 'equilibrium', 'A buffer solution is characterized by its ability to resist significant change in:', '["pH upon addition of small amounts of acid or base", "Volume upon heating", "Color upon dilution", "Temperature upon stirring"]', 0, 'A buffer solution, typically a weak acid with its conjugate base (or vice versa), resists large pH changes when small amounts of acid or base are added.', 'beginner'),
('education', 'jee/chemistry', 'thermodynamics-chem', 'For an exothermic reaction, the enthalpy change (delta H) is:', '["Negative", "Positive", "Always zero", "Undefined"]', 0, 'An exothermic reaction releases heat to the surroundings, so the system''s enthalpy decreases, giving a negative delta H.', 'beginner'),
('education', 'jee/chemistry', 'thermodynamics-chem', 'Hess''s Law states that the total enthalpy change for a reaction is:', '["Independent of the path or number of steps taken, depending only on initial and final states", "Dependent on the specific reaction pathway", "Always equal to zero for any multi-step reaction", "Only valid for exothermic reactions"]', 0, 'Hess''s Law follows from enthalpy being a state function: the total enthalpy change depends only on the initial and final states, not the path taken.', 'intermediate'),
('education', 'jee/chemistry', 'thermodynamics-chem', 'The Gibbs Free Energy change is related to enthalpy and entropy changes by the equation:', '["delta G = delta H - T delta S", "delta G = delta H + T delta S", "delta G = T delta H - delta S", "delta G = delta H x T delta S"]', 0, 'The Gibbs-Helmholtz equation: delta G = delta H - T delta S, combining enthalpy, temperature, and entropy to determine spontaneity.', 'intermediate'),
('education', 'jee/chemistry', 'thermodynamics-chem', 'A reaction is thermodynamically spontaneous (at constant temperature and pressure) when:', '["delta G is negative", "delta G is positive", "delta G is zero", "delta H alone is negative, regardless of delta S"]', 0, 'A negative Gibbs Free Energy change (delta G < 0) indicates a spontaneous process at constant temperature and pressure.', 'beginner'),
('education', 'jee/chemistry', 'thermodynamics-chem', 'Entropy is best described as a measure of the:', '["Disorder or randomness of a system", "Total energy of a system", "Temperature of a system", "Mass of a system"]', 0, 'Entropy quantifies the degree of disorder or the number of possible microscopic arrangements (microstates) of a system.', 'beginner'),
('education', 'jee/chemistry', 'organic-basic', 'In IUPAC nomenclature, the parent chain of an organic compound is chosen as the:', '["Longest continuous chain of carbon atoms", "Shortest chain containing a functional group", "Chain with the fewest branches, regardless of length", "Chain containing the most hydrogen atoms"]', 0, 'IUPAC nomenclature rules select the longest continuous carbon chain (that includes the principal functional group) as the parent chain for naming.', 'beginner'),
('education', 'jee/chemistry', 'organic-basic', 'Structural isomers are compounds that have the:', '["Same molecular formula but different structural arrangement of atoms", "Same structural arrangement but different molecular formula", "Same physical properties but different molecular formula", "Identical structure and molecular formula"]', 0, 'Structural isomers share an identical molecular formula but differ in how their atoms are connected.', 'beginner'),
('education', 'jee/chemistry', 'organic-basic', 'The inductive effect refers to:', '["The permanent displacement of sigma-bond electrons along a carbon chain due to electronegativity differences", "The temporary shift of pi electrons during a reaction", "Delocalization of electrons across a conjugated system", "The formation of hydrogen bonds between molecules"]', 0, 'The inductive effect is a permanent polarization of sigma bonds caused by a difference in electronegativity, transmitted (with diminishing strength) along a carbon chain.', 'intermediate'),
('education', 'jee/chemistry', 'organic-basic', 'Resonance stabilizes a molecule or ion primarily by:', '["Delocalizing electrons across multiple contributing structures", "Increasing the total number of atoms in the molecule", "Converting all sigma bonds into pi bonds", "Removing all lone pairs from the structure"]', 0, 'Resonance describes the delocalization of pi electrons or lone pairs across multiple resonance structures, which lowers the overall energy and stabilizes the actual (hybrid) structure.', 'intermediate'),
('education', 'jee/chemistry', 'organic-basic', 'A nucleophile is best described as a species that is:', '["Electron-rich and donates an electron pair to form a new bond", "Electron-deficient and accepts an electron pair", "Always negatively charged only", "Unreactive toward electrophiles"]', 0, 'A nucleophile is an electron-rich species (often bearing a lone pair or negative charge) that donates an electron pair to an electrophile to form a new covalent bond.', 'beginner'),
('education', 'jee/chemistry', 'hydrocarbons', 'The general formula for the alkene series of hydrocarbons is:', '["CnH2n", "CnH2n+2", "CnH2n-2", "CnHn"]', 0, 'Alkenes, containing one carbon-carbon double bond, follow the general formula CnH2n.', 'beginner'),
('education', 'jee/chemistry', 'hydrocarbons', 'According to Markovnikov''s Rule, when HX adds to an unsymmetrical alkene, the hydrogen atom preferentially attaches to the carbon that:', '["Already has the greater number of hydrogen atoms", "Has the fewer number of hydrogen atoms", "Is part of the longer chain segment", "Is closer to any existing functional group"]', 0, 'Markovnikov''s Rule (informally, "the rich get richer") states that H adds to the carbon already bearing more hydrogen atoms, while X adds to the more substituted carbon.', 'intermediate'),
('education', 'jee/chemistry', 'hydrocarbons', 'Benzene predominantly undergoes ___ reactions rather than addition reactions, due to its aromatic stability.', '["Electrophilic substitution", "Nucleophilic addition", "Electrophilic addition", "Free radical addition"]', 0, 'Benzene favors electrophilic substitution over addition because substitution preserves its stable, delocalized aromatic ring system, which addition would disrupt.', 'intermediate'),
('education', 'jee/chemistry', 'hydrocarbons', 'According to Huckel''s Rule, a planar, cyclic, fully conjugated ring is aromatic if it contains a number of pi electrons equal to:', '["4n+2 (for a non-negative integer n)", "4n (for a non-negative integer n)", "Exactly 6, and no other number", "n^2, for any integer n"]', 0, 'Huckel''s Rule defines aromaticity for planar, cyclic, conjugated systems with (4n+2) pi electrons, where n = 0, 1, 2, ... (benzene, with 6 pi electrons, is the n=1 case).', 'intermediate'),
('education', 'jee/chemistry', 'hydrocarbons', 'The general formula for the alkyne series of hydrocarbons is:', '["CnH2n-2", "CnH2n", "CnH2n+2", "CnHn"]', 0, 'Alkynes, containing a carbon-carbon triple bond, follow the general formula CnH2n-2.', 'beginner'),
('education', 'jee/chemistry', 'carbonyl-compounds', 'Both aldehydes and ketones are characterized by the presence of a:', '["Carbonyl group (C=O)", "Hydroxyl group (-OH)", "Carboxyl group (-COOH)", "Amino group (-NH2)"]', 0, 'The carbonyl group, C=O, is the defining functional group common to both aldehydes and ketones.', 'beginner'),
('education', 'jee/chemistry', 'carbonyl-compounds', 'Aldehydes are generally more reactive than ketones toward nucleophilic addition primarily because:', '["They have less steric hindrance and weaker electron donation to the carbonyl carbon", "They contain more oxygen atoms", "Their carbonyl carbon is negatively charged", "Ketones lack a carbonyl group entirely"]', 0, 'Aldehydes have only one alkyl/aryl group (versus two in ketones) attached to the carbonyl carbon, giving less steric hindrance and less electron-donating (+I) effect, making the carbonyl carbon more electrophilic and reactive.', 'intermediate'),
('education', 'jee/chemistry', 'carbonyl-compounds', 'Carboxylic acids show acidic character mainly because the resulting carboxylate ion is stabilized by:', '["Resonance delocalization of the negative charge over two oxygen atoms", "Its large molecular size", "Hydrogen bonding with water alone", "The absence of any oxygen atoms"]', 0, 'The negative charge in a carboxylate ion (RCOO-) is delocalized equally over both oxygen atoms via resonance, which stabilizes the ion and increases the acid''s tendency to lose a proton.', 'intermediate'),
('education', 'jee/chemistry', 'carbonyl-compounds', 'Tollens'' reagent (ammoniacal silver nitrate) is used to distinguish aldehydes from ketones because it gives a positive silver mirror test with:', '["Aldehydes only, not ketones", "Ketones only, not aldehydes", "Both aldehydes and ketones equally", "Neither aldehydes nor ketones"]', 0, 'Aldehydes are readily oxidized by Tollens'' reagent, depositing metallic silver (the silver mirror test); ketones generally do not react, allowing the two to be distinguished.', 'intermediate'),
('education', 'jee/chemistry', 'carbonyl-compounds', 'The acid-catalyzed reaction of a carboxylic acid with an alcohol to form an ester is known as:', '["Esterification (Fischer esterification)", "Saponification", "Hydrolysis", "Decarboxylation"]', 0, 'Fischer esterification is the acid-catalyzed reaction between a carboxylic acid and an alcohol, producing an ester and water.', 'beginner'),
('education', 'jee/chemistry', 'periodic-table', 'Moving left to right across a period, the ionization energy of elements generally:', '["Increases", "Decreases", "Remains constant", "Increases then sharply drops to zero"]', 0, 'Across a period, increasing nuclear charge pulls valence electrons more tightly, generally increasing the energy required to remove an electron.', 'beginner'),
('education', 'jee/chemistry', 'periodic-table', 'Moving left to right across a period, the atomic radius of elements generally:', '["Decreases", "Increases", "Remains constant", "Increases then decreases"]', 0, 'Across a period, increasing nuclear charge pulls the electron cloud inward (with electrons added to the same shell), generally decreasing atomic radius.', 'beginner'),
('education', 'jee/chemistry', 'periodic-table', 'Electronegativity generally ___ across a period (left to right) and ___ down a group.', '["Increases; decreases", "Decreases; increases", "Increases; increases", "Decreases; decreases"]', 0, 'Electronegativity generally increases across a period (greater nuclear pull on bonding electrons) and decreases down a group (increasing atomic size and shielding).', 'intermediate'),
('education', 'jee/chemistry', 'periodic-table', 'The s-block of the periodic table consists of which groups of elements?', '["Alkali metals (Group 1) and alkaline earth metals (Group 2)", "Halogens and noble gases", "Transition metals only", "Lanthanides and actinides"]', 0, 'The s-block comprises Group 1 (alkali metals) and Group 2 (alkaline earth metals), whose valence electrons occupy an s-subshell.', 'beginner'),
('education', 'jee/chemistry', 'periodic-table', 'The d-block elements of the periodic table are also commonly known as the:', '["Transition elements", "Representative elements", "Inner transition elements", "Noble gases"]', 0, 'The d-block elements, characterized by partially filled d-subshells, are commonly referred to as the transition elements or transition metals.', 'beginner')
